// wasm func 3721 - name inferred. Body of CEleitores::GetCurrentAbrangenciaEleitor (line 497, whose
// srcloc sits in 7377) once the current voter is known; also used by GetQtdAptos, DynamicCreate and
// the voter-state machine. Decides which cargos a voter may vote for in THIS urna:
//   no temporary transfer (decorator +48 == 0), or domicile município == urna município -> MUNICIPAL
//   same UF (decorator +52) as the urna                                                 -> ESTADUAL
//   otherwise                                                                           -> FEDERAL
md::ETipoAbrangencia GetAbrangenciaEleitor(const CEleitorDetalhe& detalhe, const std::string& uf,
                                           TMunicipioID municipio)
{
    const md::CEleitorDecorator& e = detalhe.GetEleitor();
    if (e.GetTipoTransferenciaTemporaria() == 0 || e.GetMunicipioDomicilio() == municipio)
        return md::ETipoAbrangencia::MUNICIPAL;
    return e.GetUFDomicilio() == uf ? md::ETipoAbrangencia::ESTADUAL : md::ETipoAbrangencia::FEDERAL;
}

// Comparators passed as function pointers to std::sort in CompleteLoad
//   wasm 11532 (table slot 2386): md::CImpedido by identity (+4 string, then +16 tipo)
//   wasm 11531 (table slot 2387): md::CEleitorDinamico by identity (+0 string, then +12 tipo)
bool ComparaImpedido(const md::CImpedido& a, const md::CImpedido& b) { return a.GetIdentidade() < b.GetIdentidade(); }
bool ComparaDinamico(const md::CEleitorDinamico& a, const md::CEleitorDinamico& b) { return a.GetTitulo() < b.GetTitulo(); }

