// wasm func 2824 - IDataSourceAptos slot 0 (name inferred). Used by the BU QR code (APTA/APTS/APTT),
// by CDataSourcesRelatorio::GetLinhasEleitoresAptos (BU/zerésima "eleitores aptos" line) and by
// vota::CGravaResultado. Counts every voter who may vote in the current round, once for his own
// abrangência and once for each wider one (a MUNICIPAL voter also counts for ESTADUAL and FEDERAL).
std::map<md::ETipoAbrangencia, SQtdeAptos> CEleitores::GetQtdAptos() const
{
    std::map<md::ETipoAbrangencia, SQtdeAptos> qtd;
    for (const auto abr : std::vector{md::ETipoAbrangencia::MUNICIPAL, md::ETipoAbrangencia::ESTADUAL,
                                      md::ETipoAbrangencia::FEDERAL})
        qtd[abr] = SQtdeAptos{};

    for (const auto& [identidade, detalhe] : GetContainer()) {
        if (!detalhe.PodeVotar())                                   // comum_f2266: impedimento do turno
            continue;
        const md::ETipoAbrangencia abr = GetAbrangenciaEleitor(detalhe, m_uf, m_municipio);
        if (abr > md::ETipoAbrangencia::FEDERAL)
            continue;
        std::vector<md::ETipoAbrangencia> abrangencias;
        for (auto a = abr;; a = md::ETipoAbrangencia(int(a) + 1)) {
            abrangencias.push_back(a);
            if (a == md::ETipoAbrangencia::FEDERAL)
                break;
        }
        const bool tte = detalhe.GetEleitor().GetTipoTransferenciaTemporaria() != 0;
        for (const auto a : abrangencias) {
            if (!tte)
                ++qtd[a].qtdAptosSecao;
            else
                ++qtd[a].qtdAptosTTE;
        }
    }
    return qtd;
}

// wasm func 2825 (srcloc lines 435, 439, 447)
void CEleitores::MarcaEleitorFoiHabilitado(const CEleitorDadosHabilitacao& dados)
{
    CEleitorDetalhe* detalhe = GetCurrent();                         // CDataMap::GetCurrent (656)
    if (detalhe == nullptr)
        throw CErroDados(EUeComumDadosError{7842}, "Item inexistente");
    if (!detalhe->TemDinamico())
        throw CErroDados(EUeComumDadosError{7843}, "Dados dinâmicos não carregados");
    if (detalhe->GetDinamico().GetEstadoComparecimento() == md::EEstadoComparecimento::VOTOU)
        throw CErroDados(EUeComumDadosError{7844}, "Eleitor já votou");

    detalhe->MarcaHabilitado(dados);        // CEleitorDetalhe::MarcaHabilitado, inlined (celeitordetalhe.cpp)
}

// wasm func 5761 (srcloc lines 301, 305, 358). Only caller: the "gera dados dinâmicos" step
// (6737 = vota::CInformacaoEleitor::GerarDadosDinamicos per u02, called by votaInit and
// vota::CGeraDadosDinamicos::StartState), once for the uenux.db of each flash, both in the CURRENT
// round's work directory: CPath::GetPathTrab(interna, turno)/uenux.db (shared_f2826 -> /dsk/fi/...)
// then GetPathTrab(externa, turno)/uenux.db (api_f5762 -> /dsk/fe/...). Skipped when fase == '3' and
// the urna is in "treinamento do eleitor" mode (comum_f697) - the case of the web simulator.
void CEleitores::DynamicCreate(const std::string& arquivoBanco) const
{
    if (GetContainer().empty())
        throw CErroDados(EUeComumDadosError{7837}, "Não há informações carregadas");
    if (GetContainer().begin()->second.TemDinamico())
        throw CErroDados(EUeComumDadosError{7838}, "Informações dinâmicas já carregadas");

    // Which abrangências have at least one cargo in this urna (linear std::find over the set).
    bool temMunicipal = false, temEstadual = false, temFederal = false;
    if (!m_abrangenciasCargos.empty()) {
        temMunicipal = std::ranges::find(m_abrangenciasCargos, md::ETipoAbrangencia::MUNICIPAL) != m_abrangenciasCargos.end();
        temEstadual  = std::ranges::find(m_abrangenciasCargos, md::ETipoAbrangencia::ESTADUAL)  != m_abrangenciasCargos.end();
        temFederal   = std::ranges::find(m_abrangenciasCargos, md::ETipoAbrangencia::FEDERAL)   != m_abrangenciasCargos.end();
    }

    std::vector<md::CEleitorDinamico> novos;
    for (const auto& [chave, detalhe] : GetContainer()) {
        const md::CEleitorIdentidade id =
            detalhe.GetEleitor().GetIdentidadePorTipo(detalhe.GetEleitor().GetTipoIdentificadorPrincipal());
        bool temCargo = false;
        switch (GetAbrangenciaEleitor(detalhe, m_uf, m_municipio)) {
        case md::ETipoAbrangencia::MUNICIPAL: temCargo = temMunicipal || temEstadual || temFederal; break;
        case md::ETipoAbrangencia::ESTADUAL:  temCargo = temEstadual || temFederal; break;
        case md::ETipoAbrangencia::FEDERAL:   temCargo = temFederal; break;
        default:                              temCargo = false; break;
        }
        // md::CEleitorDinamico(titulo, identidadeHabilitacao, estado) - wasm 2800
        novos.emplace_back(id, id, temCargo ? md::EEstadoComparecimento::FALTOU
                                            : md::EEstadoComparecimento::SEM_CARGO_PARA_VOTAR);
    }

    dao::CEleitorDinamicoDAO dao(arquivoBanco);              // creates table eleitor_dinamico if needed
    std::vector<md::CEleitorDinamico> existentes = dao.SelectAll();   // vtable slot 8 (3766)
    if (existentes.empty()) {
        dao.GetConexao().BeginTransaction();                 // connection vtable slot 2      // ?
        for (const auto& d : novos)
            dao.Insert(d);                                   // vtable slot 3 (5776)
        dao.GetConexao().Commit();                           // connection vtable slot 3      // ?
    } else {
        // Re-running over an existing database is accepted only if it holds exactly the same rows.
        std::sort(existentes.begin(), existentes.end());     // operator< = by titulo (wasm 3762 ...)
        std::sort(novos.begin(), novos.end());
        if (existentes != novos)                             // md::CEleitorDinamico::operator== (inlined)
            throw CErroDados(EUeComumDadosError{7839},
                             std::format("Já existem informações dinâmicas no banco {}", arquivoBanco));
    }
}

// wasm func 6734 (srcloc lines 205, 219, 238). In the binary this body is inlined into a wrapper
// (vota::CInformacaoEleitor::CarregarDadosDinamicos, u02's name) that also loads rdv.dat, the
// justificativas and the mesários (see u04-foreign-fragments.cpp); the wrapper runs it only when
// CEstadoGeralVota.treinamentoEleitor (+72) is false. Arguments: CPath::Estatico() and
// GetPathTrab(interna, turno)/uenux.db (shared_f2826).
void CEleitores::CompleteLoad(const std::string& dirEstatico, const std::string& arquivoBanco)
{
    if (!std::filesystem::exists(arquivoBanco))                                   // api_f412
        throw CErroDados(EUeComumDadosError{7834}, std::format("Não existe o arquivo {}", arquivoBanco));

    std::vector<std::string> arquivosImpedidos;                                   // api_f1936
    for (const auto& nome : m_arquivosImpedidos)
        arquivosImpedidos.push_back(dirEstatico + nome);
    std::vector<md::CImpedido> impedidos = GetEleitoresImpedidos(arquivosImpedidos);   // api_f5767
    std::vector<md::CEleitorDecorator> eleitores = GetEleitoresEstaticos(dirEstatico);  // api_f5772
    std::vector<md::CEleitorDinamico> dinamicos;
    {
        dao::CEleitorDinamicoDAO dao(arquivoBanco);
        dinamicos = dao.SelectAll();                                              // vtable slot 8
    }
    std::sort(impedidos.begin(), impedidos.end(), ComparaImpedido);               // 3765
    std::sort(dinamicos.begin(), dinamicos.end(), ComparaDinamico);               // 5766

    // Static roll and SQLite rows must describe the same voters, in the same (sorted) order.
    // (Note: the static roll is NOT sorted here; GetEleitoresEstaticos returns it sorted.)   // ?
    auto divergencia = [] {
        return CErroDados(EUeComumDadosError{7835}, "Havia divergência entre os títulos dinâmicos e os estáticos");
    };
    if (eleitores.size() != dinamicos.size())
        throw divergencia();
    for (std::size_t i = 0; i < eleitores.size(); ++i) {
        const auto id = eleitores[i].GetIdentidadePorTipo(eleitores[i].GetTipoIdentificadorPrincipal());
        if (!(id == dinamicos[i].GetTitulo()))
            throw divergencia();
    }

    Container novos;
    std::map<md::CEleitorIdentidade, md::CEleitorIdentidade> identidades;
    std::size_t indiceImpedido = 0;
    std::uint32_t qtdVotaram = 0;
    for (std::size_t i = 0; i < eleitores.size(); ++i) {
        const md::CEleitorDecorator& eleitor = eleitores[i];
        ValidaIdentidadesEleitor(eleitor);
        const md::CEleitorIdentidade principal = eleitor.GetIdentidadePorTipo(eleitor.GetTipoIdentificadorPrincipal());
        const std::vector<md::CEleitorIdentidade> ids = eleitor.GetIdentificadores();   // copy
        auto [it, inserido] = novos.try_emplace(principal,
                                                LoadEleitorDetalhe(eleitor, impedidos, indiceImpedido, &dinamicos[i]));
        if (!inserido)
            throw CErroDados(EUeComumDadosError{7836},
                             std::format("Identificador principal {} duplicado", principal.GetNumero()));  // string_view arg
        const auto estado = dinamicos.at(i).GetEstadoComparecimento();
        for (const auto& id : ids)
            identidades.emplace(id, principal);                 // every identifier -> principal one
        qtdVotaram += (estado == md::EEstadoComparecimento::VOTOU);
    }

    SetContainer(std::move(novos));                             // also resets the current iterator
    m_qtdVotaram = qtdVotaram;
    m_identidadePrincipal = std::move(identidades);
    m_dinamicosCarregados = true;
}

// wasm func 5764 (srcloc celeitores.cpp:719 + inlined CEleitorDetalhe ctor celeitordetalhe.cpp:49 +
// md::CImpedido::GetImpedimentoP2 cimpedido.cpp:46). Observed executing (from StaticLoad at start-up).
// Merge-join of the (sorted) voter roll with the (sorted) impediment list: `indiceImpedido` walks
// the impediment list in step with the caller's walk over the voters.
CEleitorDetalhe CEleitores::LoadEleitorDetalhe(const md::CEleitorDecorator& eleitor,
                                               const std::vector<md::CImpedido>& impedidos,
                                               std::size_t& indiceImpedido,
                                               const md::CEleitorDinamico* dinamico) const
{
    md::ETipoImpedimento p1 = md::ETipoImpedimento::NENHUM;
    md::ETipoImpedimento p2 = md::ETipoImpedimento::NENHUM;
    if (indiceImpedido < impedidos.size()) {
        const md::CImpedido& impedido = impedidos[indiceImpedido];           // 32 bytes
        const auto id = eleitor.GetIdentidadePorTipo(eleitor.GetTipoIdentificadorPrincipal());
        if (id == impedido.GetIdentidade()) {
            ++indiceImpedido;
            p1 = impedido.GetImpedimentoP1();                                // +20
            // cimpedido.cpp:46: throws 8068 "Não há informação de 2o turno" when absent
            p2 = impedido.TemImpedimentoP2() ? impedido.GetImpedimentoP2() : md::ETipoImpedimento::NENHUM;
        } else if (id > impedido.GetIdentidade()) {
            // The current impediment is smaller than every remaining voter: it matches nobody.
            const auto& idImp = impedido.GetIdentidade();
            throw CErroDados(EUeComumDadosError{7851},
                std::format("CEleitores::LoadEleitorDetalhe - ({}-{} > {}-{}). {} com marcação de impedido "
                            "não encontrado nas listas de eleitores e de tte",
                            id.GetNumero(), id.GetTipo(), idImp.GetNumero(), idImp.GetTipo(), idImp.GetNumero()));
        }
    }
    if (dinamico == nullptr)
        return CEleitorDetalhe(eleitor, p1, p2);
    return CEleitorDetalhe(eleitor, *dinamico, p1, p2);
}

// wasm func 5765 (srcloc line 738)
void CEleitores::ValidaIdentidadesEleitor(const md::CEleitorDecorator& eleitor) const
{
    for (const auto& id : eleitor.GetIdentificadores())
        if (id.GetTipo() == m_tipoIdentificadorPrincipal)
            return;
    // format args (packed kinds 431 = handle, string_view): the enum (formatted as an integer) and
    // only the NUMBER string of the voter's principal identity.
    throw CErroDados(EUeComumDadosError{7852},
        std::format("Identificador principal ({}) ausente para o eleitor ({})", m_tipoIdentificadorPrincipal,
                    eleitor.GetIdentidadePorTipo(eleitor.GetTipoIdentificadorPrincipal()).GetNumero()));
}

// wasm func 6034 - name inferred. Called through comum_f2821 (tipo 1), comum_f1935 (tipo 2) and the
// twin comum_f2822 (tipo 0, not in u04): the BU QR-code counters HBBM / HBBG / HBSB and the BU.
std::uint16_t CEleitores::QtdVotaramPorTipoHabilitacao(md::ETipoHabilitacao tipo) const
{
    std::uint16_t qtd = 0;
    for (const auto& [id, detalhe] : GetContainer()) {
        if (!detalhe.TemDinamico())
            continue;
        if (detalhe.GetDinamico().GetTipoHabilitacao() != tipo)
            continue;
        qtd += detalhe.GetDinamico().GetEstadoComparecimento() == md::EEstadoComparecimento::VOTOU;
    }
    return qtd;
}

