// wasm func 11529 (srcloc line 756)
std::string CEleitorDadoNomeParaUrna::Text(const std::string& formato)
{
    const CEleitorDetalhe* detalhe = CEleitores::GetInst().GetCurrent();
    if (detalhe == nullptr)
        throw CErroDados(EUeComumDadosError{7854}, "Não posicionado no eleitor corretamente");
    const md::CEleitorDecorator& e = detalhe->GetEleitor();
    const std::string& nome = e.GetNomeSocial().empty() ? e.GetNome() : e.GetNomeSocial();
    const std::string nomeParaUrna = nome.substr(0, 40);
    return std::vformat(formato, std::make_format_args(nomeParaUrna));
}

